import {newTransport,NIGERIAN_STATES,FLOWS} from './lifecycle.mjs';
import {createFeatures} from './features.mjs';
import {STAGES,clean,newShipment,addEvent,trackingUrl,validateBackup,validateOnboarding,upgradeData,visibleShipments,historyRelation} from './core.mjs';
const app=document.querySelector('#app');
const paths={logout:'<path d="M10 3H4v18h6M9 12h13m-5-5 5 5-5 5"/>',up:'<path d="M6 18 18 6M6 6h12v12"/>',box:'<path d="m3 7 9-5 9 5v10l-9 5-9-5Z"/><path d="m3 7 9 5 9-5M12 12v10M7 4.8l10 5"/>',home:'<path d="m3 10 9-7 9 7-1 10H4Z"/><path d="M9 16c2 2 4 2 6 0"/>',plus:'<path d="M12 4v16M4 12h16"/>',user:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2Z"/>',arrow:'<path d="m14 6-6 6 6 6"/>',share:'<circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m9 10 6-4M9 14l6 4"/>',search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 6 6"/>',map:'<path d="m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2ZM9 3v16M15 5v16"/>',pin:'<path d="M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 1 1 14 0Z"/><circle cx="12" cy="9" r="2.5"/>',bell:'<path d="M5 17h14l-2-4V9a5 5 0 0 0-10 0v4ZM10 21h4M12 2v2"/>',bike:'<circle cx="5" cy="17" r="4"/><circle cx="19" cy="17" r="4"/><path d="m5 17 5-9 6 9H5m6-13h4m0 0 4 13M8 8h5"/>',shop:'<path d="M4 10v11h16V10M2 6l2-4h16l2 4v4H2ZM9 21v-7h6v7"/><path d="M7 6v4M12 6v4M17 6v4"/>',check:'<path d="m5 12 5 5 9-10"/>',phone:'<path d="m5 3 4 1 1 5-3 2c1 3 3 5 6 6l2-3 5 1 1 4c-6 7-24-11-16-16Z"/>',message:'<path d="M21 11a9 9 0 0 1-9 9H3l2-5a9 9 0 1 1 16-4Z"/><path d="M8 10h8M8 14h5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',truck:'<path d="M2 5h12v13H2ZM14 10h5l3 4v4h-8"/><circle cx="6" cy="19" r="2"/><circle cx="18" cy="19" r="2"/>',shield:'<path d="m12 2 9 4v6c0 6-9 10-9 10S3 18 3 12V6Z"/><path d="m8 12 3 3 5-6"/>'};
const icon=k=>`<svg viewBox="0 0 24 24" aria-hidden="true">${paths[k]||paths.box}</svg>`;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let storageError=false;
function read(){try{return JSON.parse(localStorage.getItem('trackship-v1'))||{};}catch{storageError=true;return {};}}
let data=upgradeData(read());
let view='home',selected=null,filter='All',query='',setupRole=null,setupStep=0,setupDraft={},introIndex=0,createStep=0,shipmentDraft={},submitting=false,syncing=false,modal=false;
let gate=data.activeRole&&data.accounts[data.activeRole]?'app':data.loggedOut?'intro':data.introSeen?'role':'splash';
const activeRole=()=>data.activeRole||'vendor';
const rider=()=>activeRole()==='rider';
const account=()=>data.accounts[activeRole()]||{};
const jobs=()=>visibleShipments(data,activeRole());
const current=()=>jobs().find(s=>s.id===selected);
const live=s=>Boolean(data.connection&&s.synced&&!s.remoteBase);
const terminal=s=>['Delivered','Cancelled'].includes(s.status);
function commit(next){try{localStorage.setItem('trackship-v1',JSON.stringify(next));data=next;return true;}catch{storageError=true;toast('Unable to save. Free some phone storage and try again.');return false;}}
function toast(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('show'),4500);}
const date=s=>new Date(s).toLocaleString('en-NG',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const day=s=>s?new Date(s).toLocaleDateString('en-NG',{day:'2-digit',month:'short',year:'2-digit'}):'Not set';
const money=n=>Number(n)>0?new Intl.NumberFormat('en-NG',{style:'currency',currency:'NGN',maximumFractionDigits:0}).format(n):'Not declared';
const brand=()=>`<div class="brand">${icon('box')}TrackShip<small>NG</small></div>`;
const badge=s=>`<span class="badge ${s==='Delivered'?'green':s==='Created'||s==='Picked up'?'blue':s==='Cancelled'?'gray':''}">${s==='In transit'?'Transit':s==='Created'?'Pending':esc(s)}</span>`;
const progress=(n,total=3)=>`<div class="progress" aria-label="Step ${n+1} of ${total}">${Array.from({length:total},(_,i)=>`<span class="${i<=n?'active':''}"></span>`).join('')}</div>`;
function input(label,name,placeholder='',opts='',value=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" placeholder="${placeholder}" value="${esc(value)}" ${opts}></div>`;}
function heading(title,back='home'){return `<header class="page-heading"><button class="back" data-nav="${back}" aria-label="Go back">${icon('arrow')}</button><h1>${title}</h1></header>`;}
function navigate(next){view=next;if(next==='create'){createStep=0;shipmentDraft={size:'Small',service:'Standard',deliveryType:'intrastate',originState:'FCT Abuja',destinationState:'FCT Abuja',sender:data.profile.name,origin:data.accounts.vendor?.city||'',pickupAddress:data.accounts.vendor?.pickupAddress||''};}render();}
function nav(){const items=rider()?[['home','home','Home'],['shipments','box','My deliveries'],['add-job','plus','Add delivery'],['track','map','Track'],['profile','user','Profile']]:[['home','home','Home'],['shipments','box','Packages'],['create','plus','Send package'],['track','map','Track'],['profile','user','Profile']];return `<nav class="bottomnav" aria-label="Main navigation">${items.map(([id,i,label])=>`<button class="navitem ${view===id?'active':''}" data-nav="${id}" aria-label="${label}">${icon(i)}<span>${label}</span></button>`).join('')}</nav>`;}
function render(){
 if(location.pathname.startsWith('/t/'))return;
 if(gate!=='app'){renderGate();return;}
 if(rider()&&view==='create')view='add-job';
 app.innerHTML=`<div class="shell"><header class="topbar">${brand()}<div class="top-actions"><button class="logout-button" id="dashboard-logout" aria-label="Log out">${icon('logout')}Log out</button><button class="circle avatar" data-nav="profile" aria-label="Your profile">${esc((account().fullName||account().ownerName||data.profile.name||'T')[0].toUpperCase())}</button><button class="circle" data-nav="notifications" aria-label="Delivery updates">${icon('bell')}</button></div></header><main>${storageError?'<div class="note warn">Phone storage could not be read or saved. Export a backup before entering important information.</div>':''}${({home,shipments,create,detail,success,profile,track,'add-job':addJob,notifications,bulk:()=>features.bulk(),wallet:()=>features.wallet(),secure:()=>features.secure()})[view]?.()||home()}</main>${nav()}</div>${modal?confirmation():''}`;
 window.scrollTo(0,0);bind();features.afterRender(view);
}
function renderGate(){
 features.theme();
 if(gate==='pin-setup'||gate==='unlock'){renderLock();return;}
 if(gate==='splash'){app.innerHTML=`<main class="onboard splash">${brand()}<p>DELIVER WITH CONFIDENCE</p><span class="spinner" aria-label="Loading"></span></main>`;return;}
 if(gate==='intro'){
  const slides=[['Welcome to<br>TrackShip NG','From your first pickup to the final doorstep. A better delivery experience starts here.','courier-photo.png'],['Every package.<br>One clear journey.','Keep your deliveries in view, share progress and make every handoff feel effortless.','route.svg'],['Your business.<br>Your next delivery.','Whether you sell or ride, TrackShip gives you a workspace made for the way you move.','courier-photo.png']];
  const [title,copy,image]=slides[introIndex];app.innerHTML=`<main class="onboard story"><img class="story-bg" src="/assets/${image}" alt=""><div class="story-top">${progress(introIndex)}${brand()}</div><div class="story-content"><h1>${title}</h1><p>${copy}</p><div class="story-actions"><button class="primary" id="intro-next">${introIndex===2?'Get started':'Continue'}</button><button class="textbutton" id="intro-skip">Skip</button></div></div></main>`;
  app.querySelector('#intro-next').onclick=()=>{if(introIndex<2){introIndex++;renderGate();}else finishIntro();};app.querySelector('#intro-skip').onclick=finishIntro;return;
 }
 if(gate==='role'){
  app.innerHTML=`<main class="onboard setup-page">${brand()}<p class="eyebrow">LET’S GET YOU MOVING</p><h1 style="margin-top:13px">How will you use<br>TrackShip?</h1><p class="subtitle">Two different journeys.<br>One smoother way to deliver.</p>${[['vendor','shop','I’m a vendor','Send packages, manage your orders and keep your customers updated.'],['rider','bike','I’m a rider','Manage your assigned deliveries and record every checkpoint on the road.']].map(([r,i,title,copy])=>`<button class="role-choice ${setupRole===r?'selected':''}" data-role="${r}"><span class="role-icon">${icon(i)}</span><span><h2>${title}</h2><p>${copy}</p></span><span class="role-radio"></span></button>`).join('')}<div class="setup-bottom"><button id="role-next" class="primary wide" ${setupRole?'':'disabled'}>Continue ${icon('arrow').replace('svg ','svg style="transform:rotate(180deg)" ')}</button><p class="footer-copy">You can add the other workspace later from your profile.</p>${data.activeRole?'<button class="textbutton wide" id="role-cancel">Back to my workspace</button>':''}</div></main>`;
  app.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{setupRole=b.dataset.role;renderGate();});app.querySelector('#role-next').onclick=()=>{if(!setupRole)return;if(data.loggedOut&&data.deviceLock){gate='unlock';renderGate();return;}enterChosenRole();};app.querySelector('#role-cancel')?.addEventListener('click',()=>{gate='app';render();});return;
 }
 if(gate==='setup'){
  const isVendor=setupRole==='vendor',last=setupStep===1;
  const title=isVendor?(last?'Where do you<br>send from?':'Let’s meet<br>your business.'):(last?'Your ride.<br>Your delivery area.':'Good to meet<br>you, rider.');
  const copy=isVendor?(last?'Save your usual pickup details. You can change them for each package.':'Create your vendor profile and give every delivery a familiar name.'):(last?'Tell us how and where you deliver.':'Set up your rider profile. Your deliveries will have a space of their own.');
  let fields='';
  if(isVendor&&!last)fields=input('Business name *','businessName','e.g. Bright Stores','required maxlength="80" autocomplete="organization"',setupDraft.businessName)+input('Your full name *','ownerName','The person behind the business','required maxlength="80" autocomplete="name"',setupDraft.ownerName)+input('Business phone *','phone','08012345678','required type="tel" maxlength="20" autocomplete="tel"',setupDraft.phone)+`<div class="field"><label for="category">What do you sell?</label><select name="category" id="category">${['Fashion & accessories','Beauty & personal care','Food & groceries','Electronics','Home & lifestyle','Other'].map(v=>`<option ${v===setupDraft.category?'selected':''}>${v}</option>`).join('')}</select></div>`;
  if(isVendor&&last)fields=input('Pickup city *','city','e.g. Abuja','required maxlength="80"',setupDraft.city)+input('Pickup address *','pickupAddress','Street, area and landmark','required maxlength="240"',setupDraft.pickupAddress)+`<div class="welcome-card"><h3>Your vendor workspace</h3><div class="welcome-item">${icon('box')}Create and organise shipments</div><div class="welcome-item">${icon('share')}Share delivery updates on WhatsApp</div><div class="welcome-item">${icon('truck')}Hand deliveries over to your rider</div></div>`;
  if(!isVendor&&!last)fields=input('Full name *','fullName','Your name as customers know you','required maxlength="80" autocomplete="name"',setupDraft.fullName)+input('Mobile phone *','phone','08012345678','required type="tel" maxlength="20" autocomplete="tel"',setupDraft.phone)+`<div class="welcome-card"><h3>Made for your day on the road</h3><p class="muted" style="margin-top:12px">A dedicated rider workspace for assigned deliveries, customer details and quick status updates.</p></div>`;
  if(!isVendor&&last)fields=input('Main delivery city *','city','e.g. Abuja','required maxlength="80"',setupDraft.city)+`<div class="field"><label for="vehicle">Vehicle type *</label><select id="vehicle" name="vehicle">${['Motorcycle','Bicycle','Car','Van'].map(v=>`<option ${v===setupDraft.vehicle?'selected':''}>${v}</option>`).join('')}</select></div>`+input('Vehicle registration (except bicycles)','plate','e.g. ABC-123-DE','maxlength="24"',setupDraft.plate)+`<div class="note">This creates a profile on this phone. Rider identity and vehicle documents have not been verified.</div>`;
  app.innerHTML=`<main class="onboard setup-page"><button id="setup-back" class="back" aria-label="Previous onboarding step">${icon('arrow')}</button><p class="eyebrow">${isVendor?'VENDOR':'RIDER'} SETUP · STEP ${setupStep+1} OF 2</p>${progress(setupStep,2)}<h1>${title}</h1><p class="subtitle">${copy}</p><form id="setup-form">${fields}${last?`<label class="check-label"><input name="acknowledged" type="checkbox" required> <span>${isVendor?'I’ll use customer details only to manage their deliveries.':'I’ll share accurate delivery updates and contact the sender if there is a problem.'}</span></label>`:''}<p class="error" id="setup-error" role="alert"></p><button class="primary wide" type="submit">${last?(isVendor?'Create vendor profile':'Create rider profile'):'Continue'}</button></form><p class="footer-copy">No payment is required to test TrackShip.</p></main>`;
  app.querySelector('#setup-back').onclick=()=>{captureSetup();if(setupStep>0)setupStep--;else gate='role';renderGate();};
  app.querySelector('#setup-form').onsubmit=e=>{e.preventDefault();captureSetup();let errors=validateOnboarding(setupRole,setupDraft);if(!last)errors=errors.filter(err=>!(/city|address|vehicle|registration/i.test(err)));if(errors.length){app.querySelector('#setup-error').textContent=errors[0];return;}if(!last){setupStep++;renderGate();return;}const next={...data,loggedOut:false,activeRole:setupRole,accounts:{...data.accounts,[setupRole]:{...setupDraft,completedAt:new Date().toISOString()}},introSeen:true};if(isVendor)next.profile={name:setupDraft.businessName,phone:setupDraft.phone};if(commit(next)){gate='ready';renderGate();}};return;
 }
 if(gate==='ready'){
  const isVendor=activeRole()==='vendor';app.innerHTML=`<main class="onboard setup-page">${brand()}<div class="success"><div class="success-icon">${icon('check')}</div><p class="eyebrow">${isVendor?'BUSINESS':'RIDER'} PROFILE CREATED</p><h1>${isVendor?'Your next chapter<br>starts with a delivery.':'You’re ready<br>for the road.'}</h1><p class="muted">${isVendor?'Welcome, '+esc(data.profile.name)+'. Your vendor workspace is ready.':'Welcome, '+esc(account().fullName)+'. Your rider workspace is ready.'}</p></div><div class="welcome-card"><div class="welcome-item">${icon(isVendor?'box':'bike')}${isVendor?'Send your first package':'View your assigned deliveries'}</div><div class="welcome-item">${icon('clock')}${isVendor?'Keep every checkpoint in view':'Record pickup and delivery updates'}</div><div class="welcome-item">${icon('shield')}Your details are saved on this phone</div></div><button class="primary wide" id="ready-next">${isVendor?'Start sending':'Continue to secure rider sign-on'}</button></main>`;app.querySelector('#ready-next').onclick=()=>{gate='app';view=activeRole()==='rider'?'secure':'home';render();};
 }
}
function enterChosenRole(){if(data.accounts[setupRole]){if(!commit({...data,activeRole:setupRole,loggedOut:false}))return;gate='app';view='home';selected=null;query='';filter='All';render();sync();return;}setupDraft=setupRole==='vendor'?{businessName:data.profile.name,phone:data.profile.phone,category:'Fashion & accessories'}:{vehicle:'Motorcycle'};setupStep=0;gate='setup';renderGate();}
async function pinHash(pin,salt){const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(pin),'PBKDF2',false,['deriveBits']);const bits=await crypto.subtle.deriveBits({name:'PBKDF2',hash:'SHA-256',salt:new TextEncoder().encode(salt),iterations:210000},key,256);return Array.from(new Uint8Array(bits),b=>b.toString(16).padStart(2,'0')).join('');}
function requestLogout(){if(!data.deviceLock){gate='pin-setup';renderGate();}else performLogout();}
async function performLogout(){const oldSession=data.riderConnection;features.clearTransient();if(!commit({...data,activeRole:null,loggedOut:true,riderConnection:null,riderAvailable:false})){return;}selected=null;query='';filter='All';shipmentDraft={};setupDraft={};setupRole=null;introIndex=0;modal=false;gate='intro';renderGate();if(oldSession){request(oldSession.base,'/api/auth/logout',{method:'POST',headers:{Authorization:'Bearer '+oldSession.token},body:'{}'}).catch(()=>{});}toast('Logged out. Your saved shipments are kept on this phone.');}
function renderLock(){const creating=gate==='pin-setup';app.innerHTML=`<main class="onboard setup-page pin-card">${brand()}<button class="back" id="pin-back" aria-label="Go back">${icon('arrow')}</button><p class="eyebrow">${creating?'LOCK YOUR SAVED WORKSPACES':'WELCOME BACK'}</p><h1 style="margin-top:14px">${creating?'Create your app PIN.':'Enter your app PIN.'}</h1><p class="subtitle">${creating?'Use six digits you can remember. You’ll need this PIN to return to your saved vendor or rider workspace after logging out.':'Unlock your saved '+esc(setupRole||'')+' workspace. Your shipments stay on this phone.'}</p><form id="pin-form">${input('6-digit app PIN','appPin','••••••','type="password" class="pin-input" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="off"')}${creating?input('Confirm app PIN','confirmPin','••••••','type="password" class="pin-input" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="off"'):''}<p class="error login-error" id="pin-error" role="alert"></p><button class="primary wide" type="submit">${creating?'Save PIN and log out':'Unlock workspace'}</button></form><p class="footer-copy">${creating?'Keep your PIN safe. Export a private backup before uninstalling or clearing app data.':'The app PIN locks this device. Secure rider service access still needs phone verification after logout.'}</p></main>`;app.querySelector('#pin-back').onclick=()=>{gate=creating?'app':'role';render();};app.querySelector('#pin-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button');const error=app.querySelector('#pin-error');button.disabled=true;try{const f=new FormData(e.target);const pin=f.get('appPin');if(!/^\d{6}$/.test(pin))throw new Error('Enter exactly six digits.');if(creating){if(pin!==f.get('confirmPin'))throw new Error('The two PINs do not match.');const salt=crypto.randomUUID();const hash=await pinHash(pin,salt);if(commit({...data,deviceLock:{salt,hash,attempts:0,lockedUntil:0}}))await performLogout();}else{if(Date.now()<(data.deviceLock.lockedUntil||0))throw new Error('Too many incorrect PINs. Wait five minutes before trying again.');const hash=await pinHash(pin,data.deviceLock.salt);if(hash!==data.deviceLock.hash){const attempts=(data.deviceLock.attempts||0)+1;commit({...data,deviceLock:{...data.deviceLock,attempts,lockedUntil:attempts>=5?Date.now()+300000:0}});throw new Error(attempts>=5?'Too many incorrect PINs. Wait five minutes.':'Incorrect app PIN.');}if(commit({...data,loggedOut:false,deviceLock:{...data.deviceLock,attempts:0,lockedUntil:0}}))enterChosenRole();}}catch(err){if(error)error.textContent=err.message;}finally{button.disabled=false;}};}
function captureSetup(){const form=app.querySelector('#setup-form');if(form)for(const [k,v]of new FormData(form))if(k!=='acknowledged')setupDraft[k]=clean(v,k==='pickupAddress'?240:80);}
function finishIntro(){if(commit({...data,introSeen:true})){gate='role';renderGate();}}
function stats(){const list=jobs();return `<div class="stats">${[[list.length,'Total packages','All'],[list.filter(s=>['In transit','Out for delivery','Delivery OTP sent'].includes(s.status)).length,'In transit','In transit'],[list.filter(s=>(!terminal(s)&&!['In transit','Out for delivery','Delivery OTP sent'].includes(s.status))).length,'On process','On process'],[list.filter(s=>s.status==='Delivered').length,'Delivered','Delivered']].map(([value,label,f])=>`<button class="stat" data-stat="${f}"><b>${value}</b><span>${label}</span><span class="stat-arrow">${icon('up')}</span></button>`).join('')}</div>`;}
function searchBar(){return `<div class="search-wrap">${icon('search')}<input id="search" placeholder="Search packages..." aria-label="Search packages" value="${esc(query)}"></div>`;}
function filterBar(){return `<div class="filters">${['All','Interstate','Intrastate','Awaiting handoff','Completed','On process','In transit','Cancelled'].map(f=>`<button class="filter ${filter===f?'active':''}" data-filter="${f}">${f}</button>`).join('')}</div>`;}
function matches(s){const match=filter==='All'||(filter==='Interstate'&&s.deliveryType==='interstate')||(filter==='Intrastate'&&s.deliveryType==='intrastate')||(filter==='Awaiting handoff'&&s.status.includes('handoff requested'))||(filter==='Completed'&&s.status==='Delivered')||(filter==='On process'&&(!terminal(s)&&!['In transit','Out for delivery','Delivery OTP sent'].includes(s.status)))||(filter==='In transit'&&['In transit','Out for delivery','Delivery OTP sent'].includes(s.status))||(filter==='Delivered'&&s.status==='Delivered')||(filter==='Cancelled'&&s.status==='Cancelled');return match&&`${s.code} ${s.recipient} ${s.description} ${s.origin} ${s.destination}`.toLowerCase().includes(query.toLowerCase());}
function home(){const list=jobs().filter(matches);return `<section class="intro-head"><h1>${rider()?'Your next<br><strong>Delivery.</strong>':'Track<br><strong>Shipments.</strong>'}</h1><span class="rider-chip">${rider()?'Rider':'Vendor'}</span></section>${rider()?`<div class="availability"><div><strong>${data.riderAvailable?'Ready for deliveries':'You’re currently offline'}</strong><p>Availability on this phone · ${esc(account().city||'')}</p></div><button class="toggle ${data.riderAvailable?'on':''}" id="availability" role="switch" aria-checked="${data.riderAvailable}" aria-label="Rider availability"></button></div>`:''}${searchBar()}${filterBar()}<div id="package-list">${list.length?list.slice(0,4).map((s,i)=>shipmentCard(s,i===0&&!terminal(s))).join(''):empty(rider()?'Your next delivery starts here.':'Your first package starts here.',rider()?'Deliveries assigned to your phone number appear here. You can also add a dispatch link from a vendor.':'Create a package and keep your customer in the loop.',rider()?'add-job':'create',rider()?'Add a delivery':'Send a package')}</div>${!data.connection?'<p class="copy-status">Phone-only testing · Live links need a connected service.</p>':''}`;}
function empty(title,copy,action='create',label='Send a package'){return `<section class="empty"><div class="empty-icon">${icon(rider()?'bike':'box')}</div><h3>${title}</h3><p class="muted">${copy}</p><button class="primary" data-nav="${action}">${label}</button></section>`;}
function miniJourney(s){const flow=s.workflowVersion===3?(s.flow||FLOWS[s.deliveryType]||STAGES):STAGES;const stage=flow.indexOf(s.status);return `<div class="mini-journey" aria-label="${esc(s.status)}">${(s.workflowVersion===3?[1,Math.floor((flow.length-1)/3),Math.floor(2*(flow.length-1)/3),flow.length-1]:[1,2,3,4]).map((checkpoint,i)=>`${i?`<span class="mini-line ${stage>=checkpoint?'done':''}"></span>`:''}<span class="mini-stop ${stage>=checkpoint?'done':''}">${stage>=checkpoint?'✓':'·'}</span>`).join('')}</div>`;}
function shipmentCard(s,featured=false){return `<article class="card"><button class="shipment ${featured?'featured':''}" data-open="${esc(s.id)}"><div class="package-top"><span class="package-thumb">${icon('box')}</span><div class="package-title"><h3>${esc(s.code)}</h3><p>${esc(s.description)}</p></div>${badge(s.status)}</div>${miniJourney(s)}<div class="route-row"><div><small>${esc(s.origin)}</small><b>${day(s.createdAt)}</b></div><div><small>${esc(s.destination)}</small><b>${s.deliveryDate?day(s.deliveryDate):s.status==='Delivered'?day(s.events.at(-1).at):'Date not set'}</b></div></div><small class="sync-label">${s.remoteBase?(s.dirty?'Update waiting to sync':'Rider dispatch'):s.synced&&!s.dirty?'Tracking synced':data.connection?'Waiting to sync':'Saved on this phone'}</small></button></article>`;}
function shipments(){const list=jobs().filter(matches);return `${heading(rider()?'Delivery history':'Package history')}${searchBar()}${stats()}${filterBar()}<div id="package-list">${list.length?list.map(s=>shipmentCard(s)).join(''):empty('No packages found.','Your delivery book will grow with every package.',rider()?'add-job':'create',rider()?'Add a delivery':'Send a package')}</div>`;}
function create(){
 const d=shipmentDraft;
 let fields='';
 const stateSelect=(label,name)=>`<div class="field"><label for="${name}">${label}</label><select id="${name}" name="${name}">${NIGERIAN_STATES.map(v=>`<option ${d[name]===v?'selected':''}>${v}</option>`).join('')}</select></div>`;
 if(createStep===0)fields=`<h2>Package details</h2><p class="form-help">Tell us what you’re sending.</p><label>Package size</label><div class="size-grid">${[['Small','< 2 kg'],['Medium','2–5 kg'],['Large','> 5 kg']].map(([size,weight])=>`<button type="button" class="size-option ${d.size===size?'active':''}" data-size="${size}"><strong>${esc(weight)}</strong><small>${size}</small></button>`).join('')}</div>${input('Package description *','description','e.g. Electronics, books, clothing...','required maxlength="160"',d.description)}${input('Declared value (optional)','declaredValue','₦ 0.00','type="number" min="0" max="100000000" step="0.01"',d.declaredValue)}<div class="field"><label for="notes">Special instructions</label><textarea id="notes" name="notes" maxlength="240" placeholder="Handle with care, fragile items...">${esc(d.notes)}</textarea></div>`;
 if(createStep===1)fields=`<h2>Delivery details</h2><p class="form-help">Where should we send it?</p><div class="field"><label for="deliveryType">Delivery type</label><select id="deliveryType" name="deliveryType"><option value="intrastate" ${d.deliveryType==='intrastate'?'selected':''}>Intrastate · within one state</option><option value="interstate" ${d.deliveryType==='interstate'?'selected':''}>Interstate · across states</option></select></div>${stateSelect('Pickup state','originState')}${stateSelect('Destination state','destinationState')}${input('Delivery city *','destination','e.g. Lagos','required maxlength="80"',d.destination)}${input('Delivery address *','address','Street, area and landmark','required maxlength="240"',d.address)}${input('Recipient name *','recipient','Full name','required maxlength="80"',d.recipient)}${input('Recipient phone *','phone','08012345678','required type="tel" maxlength="20"',d.phone)}${input('Sender / business name *','sender','Business name','required maxlength="80"',d.sender)}${input('Pickup city *','origin','e.g. Abuja','required maxlength="80"',d.origin)}${input('Pickup address','pickupAddress','Your usual pickup point','maxlength="240"',d.pickupAddress)}${input('Preferred delivery date (optional)','deliveryDate','','type="date"',d.deliveryDate)}`;
 if(createStep===2)fields=`<h2>Choose service</h2><p class="form-help">Record your delivery preference.</p>${[['Express','Same-day delivery requested','Confirm timing with your rider'],['Standard','2–3 business days requested','Timing depends on your delivery provider'],['Economy','5–7 business days requested','Choose a lower urgency option']].map(([service,copy,note])=>`<button type="button" class="service-option ${d.service===service?'active':''}" data-service="${service}"><strong>${service} delivery</strong><small>${copy}</small><span class="service-dot">${note}</span></button>`).join('')}${input('Total delivery fee (₦) *','deliveryFee','Agreed fee per delivery','required type="number" min="0.01" max="10000000" step="0.01"',d.deliveryFee)}${d.deliveryType==='interstate'?input('Pickup rider fee (₦) *','pickupFee','','required type="number" min="0.01" step="0.01"',d.pickupFee)+input('Carrier fee (₦) *','carrierFee','','required type="number" min="0.01" step="0.01"',d.carrierFee)+input('Last-mile rider fee (₦) *','lastMileFee','','required type="number" min="0.01" step="0.01"',d.lastMileFee):''}<p class="form-section">Assign your rider</p><p class="form-help">Optional. Use the rider’s onboarding phone number.</p>${input('Rider / logistics name','rider','Who will handle the package?','maxlength="80"',d.rider)}${input('Rider phone','riderPhone','08012345678','type="tel" maxlength="20"',d.riderPhone)}<div class="note">Service preferences do not book a carrier or guarantee an arrival time. Agree the delivery fee directly with your rider.</div>`;
 if(createStep===3)fields=`<section class="card info"><h2>Order summary</h2><div class="package-top" style="margin:24px 0"><span class="package-thumb">${icon('box')}</span><div class="package-title"><h3>${esc(d.size)} package</h3><p>${esc(d.description)}</p></div></div>${[['Recipient',d.recipient],['Phone',d.phone],['From',d.origin],['To',d.destination],['Delivery address',d.address],['Service',d.service+' delivery'],['Declared value',money(d.declaredValue)],['Rider',d.rider||'Not assigned'],['Delivery fee',money(d.deliveryFee)]].map(([k,v])=>`<div class="row"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</section><div class="note">Creating a shipment does not charge you. After syncing, use Pay delivery fee on its details page. Dispatch requires a verified payment.</div><label class="check-label"><input type="checkbox" required><span>I’ve checked the delivery details and have permission to use the recipient’s information for this delivery.</span></label>`;
 return `<header class="page-heading"><button class="back" id="create-back" aria-label="Previous package step">${icon('arrow')}</button><h1>${createStep===3?'Review shipment':'Send package'}</h1>${progress(Math.min(createStep,2))}</header><form id="shipment-form">${fields}<p class="error" id="form-error" role="alert"></p><button class="primary wide" type="submit" ${submitting?'disabled':''}>${createStep===3?'Confirm shipment':'Continue'}</button></form><p class="footer-copy">${createStep===3?'Your customer details stay private.':'Step '+(createStep+1)+' of 3 · Made for Nigerian businesses'}</p>`;
}
function captureShipment(){const form=app.querySelector('#shipment-form');if(form)for(const[k,v]of new FormData(form))shipmentDraft[k]=clean(v,['address','pickupAddress','notes'].includes(k)?240:160);}
function timeline(s){const actual=s.events;const flow=s.workflowVersion===3?(s.flow||FLOWS[s.deliveryType]||STAGES):STAGES;const pending=terminal(s)?[]:flow.slice(flow.indexOf(s.status)+1).map(status=>({status,pending:true}));return `<section class="card timeline"><h2>Tracking status</h2>${[...actual,...pending].map((e,i)=>`<div class="event ${e.pending?'pending':''}"><span class="event-icon">${icon(e.status==='Created'?'box':e.status==='Picked up'?'box':e.status==='In transit'?'truck':e.status==='Out for delivery'?'pin':e.status==='Delivered'?'check':'clock')}</span><div class="event-body"><h3>${esc(e.status==='Picked up'?'Package picked up':e.status)}</h3><p>${e.pending?'Waiting for an update':esc(e.note||'Status recorded by the delivery team')}</p>${e.at?`<time>${date(e.at)}</time>`:''}</div></div>`).join('')}</section>`;}
function detail(){const s=current();if(!s)return empty('Delivery not found.','Choose a package from your delivery book.','shipments','View packages');const next=STAGES[STAGES.indexOf(s.status)+1];return `${heading('Shipment details','shipments')}<section class="orange-summary"><div class="package-top"><span class="package-thumb">${icon('box')}</span><div class="package-title"><h3>${esc(s.code)}</h3><p style="color:#ffe7d2">${esc(s.description)}</p></div>${badge(s.status)}</div><div class="summary-lines">${[['Preferred delivery',s.deliveryDate?day(s.deliveryDate):'Not specified'],['Package size',s.size||'Not specified'],['Declared value',money(s.declaredValue)],['Delivery service',s.service||'Not specified']].map(([k,v])=>`<div class="row"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</div><button class="secondary wide" data-map="${esc(s.id)}">${icon('map')} View route</button></section>${timeline(s)}${features.workflowPanel(s,rider())}${terminal(s)?`<div class="note">${s.status==='Delivered'?'Delivery completed. This package is now closed.':'This shipment was cancelled.'}</div>`:s.workflowVersion===3?'':`<section class="card info"><h3>${rider()?'Record your checkpoint':'Update delivery'}</h3><form id="update-form"><div class="field"><label for="status">Next status</label><select id="status" name="status"><option>${next}</option>${!rider()?'<option>Cancelled</option>':''}</select></div>${input('Checkpoint / note (optional)','updateNote','e.g. Arrived at Utako terminal','maxlength="240"')}<button class="primary wide" type="submit">Save delivery update</button></form></section>`}<section class="card info"><h3>${rider()?'Your delivery details':'Package information'}</h3>${[['Sender',s.sender],['Recipient',s.recipient],['Recipient phone',s.phone],['Delivery type',s.deliveryType||'Earlier test shipment'],['Pickup state',s.originState||'Not specified'],['Destination state',s.destinationState||'Not specified'],['Pickup city',s.origin],['Pickup address',s.pickupAddress||'Contact the sender'],['Delivery city',s.destination],['Delivery address',s.address],['Rider',s.rider||'Not assigned'],['Rider phone',s.riderPhone||'Not provided'],['Instructions',s.notes||'None']].map(([k,v])=>`<div class="row"><span>${k}</span><strong>${esc(v)}</strong></div>`).join('')}</section><div class="stack">${rider()?`<button class="primary wide" id="contact">${icon('phone')} Call recipient</button>`:`<button class="primary wide" id="share">${icon('share')} ${live(s)?'Share tracking link':'Share delivery status'}</button><button class="secondary wide" id="handoff">${icon('bike')} Share with rider</button>`}${live(s)?'<button class="secondary wide" id="preview">Preview customer tracking</button>':''}</div>${s.dirty&&(data.connection||s.remoteBase)?'<div class="note warn">Changes are saved on this phone and waiting to sync.</div>':''}${s.remoteBase?'<button class="secondary wide" id="sync">Sync delivery now</button>':''}<p class="footer-copy">${s.syncedAt?'Last synced '+date(s.syncedAt):'Saved on this phone'}</p>`;}
function confirmation(){return `<div class="modal-backdrop" role="dialog" aria-modal="true" aria-label="Shipment confirmed"><div class="modal"><div class="success-icon">${icon('check')}</div><h2>Shipment created!</h2><p>Your package details are saved. Keep your customer updated at every step.</p><div class="stack"><button class="primary wide" id="modal-home">Go home</button><button class="secondary wide" id="modal-track">Track your package</button></div></div></div>`;}
function success(){const s=current();return `${heading('Shipment confirmed')}<div class="success"><div class="success-icon">${icon('check')}</div><h1>Ready for the journey.</h1><p class="muted">Your package has a place in your delivery book.</p></div>${s?shipmentCard(s,true):''}<div class="stack"><button class="primary wide" id="share">${icon('share')} Share delivery ${live(s)?'link':'status'}</button><button class="secondary wide" data-nav="detail">View shipment</button><button class="textbutton wide" data-nav="create">Send another package</button></div>`;}
function routeMap(s){return features.mapView(s);}
function track(){const list=jobs();const s=list.find(s=>s.id===selected)||list.find(s=>!terminal(s))||list[0];if(!s)return `${heading('Track package')}${empty('A journey will appear here.','Your packages and their delivery checkpoints will appear once you add a shipment.',rider()?'add-job':'create',rider()?'Add a delivery':'Send a package')}`;return `${heading('Track package','detail')}<div class="field"><label for="track-select">Choose package</label><select id="track-select">${list.map(p=>`<option value="${esc(p.id)}" ${s.id===p.id?'selected':''}>${esc(p.code)} · ${esc(p.description)}</option>`).join('')}</select></div>${routeMap(s)}<div class="stack"><button class="primary wide" data-open="${esc(s.id)}">View delivery updates</button><button class="secondary wide" id="directions" data-address="${esc(s.address+', '+s.destination+', Nigeria')}">${icon('pin')} Open delivery address in Maps</button></div>`;}
function profile(){const a=account();const role=rider()?'Rider':'Vendor';return `${heading('Your profile')}<section class="card profile-heading"><span class="avatar">${esc((a.fullName||a.businessName||'T')[0].toUpperCase())}</span><div><h2>${esc(a.fullName||a.businessName)}</h2><p>${esc(a.phone)} · ${esc(a.city)}</p><span class="role-label">${role} workspace</span></div></section><form id="profile-form">${rider()?input('Full name','fullName','Your name','required maxlength="80"',a.fullName):input('Business name','businessName','Business name','required maxlength="80"',a.businessName)+input('Your full name','ownerName','Your name','required maxlength="80"',a.ownerName)}${input(rider()?'Mobile phone':'Business phone','phone','08012345678','required type="tel" maxlength="20"',a.phone)}${input(rider()?'Delivery city':'Pickup city','city','e.g. Abuja','required maxlength="80"',a.city)}${rider()?`<div class="field"><label for="vehicle">Vehicle type</label><select id="vehicle" name="vehicle">${['Motorcycle','Bicycle','Car','Van'].map(v=>`<option ${v===a.vehicle?'selected':''}>${v}</option>`).join('')}</select></div>`+input('Vehicle registration','plate','','maxlength="24"',a.plate):input('Pickup address','pickupAddress','Street, area and landmark','required maxlength="240"',a.pickupAddress)}<p class="error" id="profile-error" role="alert"></p><button class="primary wide" type="submit">Save profile</button></form><div class="setting"><h3>Another way to move</h3><p>${rider()?'Have a business too? Open or set up your vendor workspace.':'Ride as well? Open or set up your rider workspace.'}</p><button class="secondary wide" id="switch-role">${rider()?'Switch to vendor':'Switch to rider'}</button><button class="textbutton wide" id="replay-intro">View introduction again</button></div>${!rider()?connectionSection():`<div class="setting"><h3>Your rider workspace</h3><p>Only deliveries assigned to your phone number or added using a vendor’s private dispatch link appear here. This local profile is not a verified rider account.</p></div>`}<div class="setting"><h3>Keep a backup</h3><p>Save your profiles, shipments and service access. This file includes private customer information.</p><button class="secondary wide" id="export">Export backup</button><p>Restore your data from a TrackShip backup.</p><input id="restore" type="file" accept="application/json,.json" aria-label="Restore backup"></div><div class="setting"><button class="secondary wide" id="profile-logout">Log out of ${rider()?'rider':'vendor'} workspace</button></div><p class="footer-copy">TrackShip NG · 0.3.1<br>Connected payments, custody, OTP and GPS require service activation</p>`;}
function connectionSection(){return `<div class="setting"><h3>Live tracking service</h3><p>${data.connection?`Connected to <span class="break">${esc(data.connection.base)}</span>. Synced packages can share live links and rider dispatch links.`:'The app works on this phone. Cross-phone tracking and dispatch links need your hosted TrackShip service.'}</p>${data.connection?'<button class="secondary wide" id="sync">Sync deliveries now</button>':`<form id="connect-form">${input('Tracking service address','serverUrl','https://your-service.example','type="url" required')}<button class="secondary wide" type="submit">Connect service</button><p class="error" id="connection-error" role="alert"></p></form>`}</div>`;}
function addJob(){return `${heading('Add a delivery')}<div class="empty-icon" style="margin:25px 0">${icon('bike')}</div><h2>Your next pickup.</h2><p class="muted" style="margin:12px 0 25px">Paste the private dispatch link your vendor shared with you.</p><form id="add-job-form">${input('Vendor dispatch link','dispatchLink','https://your-service.example/r/...','required type="url"')}<p class="error" id="job-error" role="alert"></p><button class="primary wide" type="submit">Add to my deliveries</button></form><div class="note">The link gives access to one delivery. Keep it private. A vendor using this same phone can assign a shipment to your rider phone number without a service connection.</div>`;}
function notifications(){const events=jobs().flatMap(s=>s.events.map(e=>({...e,shipment:s}))).sort((a,b)=>b.at.localeCompare(a.at));return `${heading('Delivery updates')}${events.length?events.slice(0,30).map(e=>`<article class="card"><button class="shipment notification" data-open="${esc(e.shipment.id)}"><span class="package-thumb">${icon(e.status==='Delivered'?'check':'box')}</span><div><h3>${esc(e.status)} · ${esc(e.shipment.code)}</h3><p>${esc(e.note||e.shipment.description)}</p><time>${date(e.at)}</time></div></button></article>`).join(''):'<div class="empty"><h3>All quiet for now.</h3><p class="muted">Delivery updates will appear here as your packages move.</p></div>'}`;}
function bind(){
 app.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));
 app.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>{selected=b.dataset.open;view='detail';render();});
 app.querySelectorAll('[data-map]').forEach(b=>b.onclick=()=>{selected=b.dataset.map;view='track';render();});
 app.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});
 app.querySelectorAll('[data-stat]').forEach(b=>b.onclick=()=>{filter=b.dataset.stat;render();});
 const search=app.querySelector('#search');if(search)search.oninput=()=>{const start=search.selectionStart;query=search.value;render();const n=app.querySelector('#search');n.focus();n.setSelectionRange(start,start);};
 app.querySelector('#dashboard-logout')?.addEventListener('click',requestLogout);
 app.querySelector('#profile-logout')?.addEventListener('click',requestLogout);
 app.querySelector('#availability')?.addEventListener('click',()=>{if(commit({...data,riderAvailable:!data.riderAvailable}))render();});
 app.querySelectorAll('[data-size]').forEach(b=>b.onclick=()=>{captureShipment();shipmentDraft.size=b.dataset.size;render();});
 app.querySelectorAll('[data-service]').forEach(b=>b.onclick=()=>{captureShipment();shipmentDraft.service=b.dataset.service;render();});
 app.querySelector('#create-back')?.addEventListener('click',()=>{captureShipment();if(createStep>0){createStep--;render();}else navigate('home');});
 app.querySelector('#shipment-form')?.addEventListener('submit',async e=>{
  e.preventDefault();if(submitting)return;captureShipment();
  const error=app.querySelector('#form-error');
  try{
   if(createStep===1&&!/^\+?[\d\s()-]{10,20}$/.test(shipmentDraft.phone||''))throw new Error('Enter a valid recipient phone number.');
   if(createStep<3){if(createStep===2)newTransport(shipmentDraft,data.profile.name);createStep++;render();return;}
   submitting=true;
   const s=newTransport(shipmentDraft,data.profile.name);
   if(!commit({...data,shipments:[s,...data.shipments]}))return;
   selected=s.id;view='success';modal=true;render();await sync();
  }catch(err){if(error)error.textContent=err.message;}finally{submitting=false;}
 });
 app.querySelector('#update-form')?.addEventListener('submit',async e=>{
  e.preventDefault();const s=current();const f=new FormData(e.target);const status=f.get('status');
  if(status==='Cancelled'&&!confirm('Cancel this shipment? This cannot be undone.'))return;
  try{const updated=addEvent(s,status,f.get('updateNote'));const collection=data.shipments.some(p=>p.id===s.id)?'shipments':'riderJobs';if(commit({...data,[collection]:data[collection].map(p=>p.id===s.id?updated:p)})){render();toast('Delivery update saved');await sync();}}catch(err){toast(err.message);}
 });
 app.querySelector('#profile-form')?.addEventListener('submit',e=>{
  e.preventDefault();const fields=Object.fromEntries(new FormData(e.target));const updated={...account(),...fields};const errors=validateOnboarding(activeRole(),updated);if(errors.length){app.querySelector('#profile-error').textContent=errors[0];return;}
  const next={...data,accounts:{...data.accounts,[activeRole()]:updated}};if(!rider())next.profile={name:fields.businessName,phone:fields.phone};if(commit(next)){render();toast('Profile saved');}
 });
 app.querySelector('#switch-role')?.addEventListener('click',()=>{setupRole=rider()?'vendor':'rider';gate='role';query='';filter='All';renderGate();});
 app.querySelector('#replay-intro')?.addEventListener('click',()=>{introIndex=0;gate='intro';renderGate();});
 app.querySelector('#share')?.addEventListener('click',()=>shareShipment());
 app.querySelector('#handoff')?.addEventListener('click',handoff);
 app.querySelector('#preview')?.addEventListener('click',()=>openLink(trackingUrl(data.connection.base,current())));
 app.querySelector('#contact')?.addEventListener('click',()=>{const number=current()?.phone?.replace(/[^+\d]/g,'');if(number)openLink('tel:'+number);});
 app.querySelector('#directions')?.addEventListener('click',e=>openLink('https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(e.currentTarget.dataset.address)));
 app.querySelector('#track-select')?.addEventListener('change',e=>{selected=e.target.value;render();});
 app.querySelector('#connect-form')?.addEventListener('submit',connect);
 app.querySelector('#sync')?.addEventListener('click',()=>sync(true));
 app.querySelector('#add-job-form')?.addEventListener('submit',importJob);
 app.querySelector('#export')?.addEventListener('click',exportData);
 app.querySelector('#restore')?.addEventListener('change',restoreData);
 app.querySelector('#modal-home')?.addEventListener('click',()=>{modal=false;navigate('home');});
 app.querySelector('#modal-track')?.addEventListener('click',()=>{modal=false;view='detail';render();});
}
function openLink(url){if(window.TrackShip)window.TrackShip.openUrl(url);else if(url.startsWith('tel:'))location.href=url;else window.open(url,'_blank','noopener,noreferrer');}
async function shareText(text){if(window.TrackShip){window.TrackShip.share(text);return;}try{if(navigator.share)await navigator.share({title:'TrackShip NG delivery',text});else{await navigator.clipboard.writeText(text);toast('Copied. Paste it into WhatsApp.');}}catch(e){if(e.name!=='AbortError')toast('Could not share. Please try again.');}}
function shareShipment(){const s=current();if(!s)return;return shareText(`${s.business}\nYour package: ${s.description}\nTracking ID: ${s.code}\n${s.origin} → ${s.destination}\nStatus: ${s.status}${live(s)?`\nTrack your delivery: ${trackingUrl(data.connection.base,s)}`:'\nThis is a status message. Contact your seller for the latest progress.'}`);}
async function handoff(){const s=current();if(!live(s)||!s.riderToken){toast('Live dispatch links need a connected service and a synced shipment.');return;}await shareText(`Private rider dispatch · ${s.code}\n${s.origin} → ${s.destination}\nOpen TrackShip’s rider workspace and add this delivery link:\n${data.connection.base}/r/${s.riderToken}\nOnly share this link with your assigned rider.`);}
async function request(base,path,options={}){const response=await fetch(base+path,{...options,signal:AbortSignal.timeout(15000),headers:{'Content-Type':'application/json',...(options.headers||{})}});const body=await response.json().catch(()=>({error:'Invalid service response.'}));if(!response.ok){const err=new Error(body.error||'Tracking service unavailable.');err.status=response.status;throw err;}return body;}
async function connect(e){e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;const error=app.querySelector('#connection-error');try{const url=new URL(new FormData(e.target).get('serverUrl'));if(url.protocol!=='https:'||url.username||url.password||url.search||url.hash||!['','/'].includes(url.pathname))throw new Error('Use your service’s HTTPS address without a path or password.');const base=url.origin;const health=await request(base,'/api/health');if(health.service!=='trackship-ng')throw new Error('That address is not a TrackShip service.');const workspace=await request(base,'/api/workspaces',{method:'POST',body:'{}'});if(commit({...data,connection:{base,token:workspace.token},shipments:data.shipments.map(s=>({...s,dirty:true,synced:false}))})){render();toast('Tracking service connected');await sync(true);}}catch(err){if(error)error.textContent=err.message;}finally{button.disabled=false;}}
async function importJob(e){return features.importJob(e);}
async function sync(announce=false){if(syncing||gate!=='app')return;syncing=true;let changed=false;let failed='';try{
 if(!data.connection&&SERVICE_URL){try{const health=await request(SERVICE_URL,'/api/health');if(health.service!=='trackship-ng')throw new Error('Unexpected service');const workspace=await request(SERVICE_URL,'/api/workspaces',{method:'POST',body:'{}'});commit({...data,connection:{base:SERVICE_URL,token:workspace.token}});}catch{if(announce)toast('The configured tracking service is unavailable.');}}
 if(data.connection){const snapshots=new Map();const activeIds=data.shipments.filter(s=>s.workflowVersion===3&&s.synced&&(!terminal(s)||s.id===selected)).map(s=>s.id);for(let i=0;i<activeIds.length;i+=100){try{const result=await request(data.connection.base,'/api/v3/shipments/snapshot',{method:'POST',headers:{Authorization:'Bearer '+data.connection.token},body:JSON.stringify({ids:activeIds.slice(i,i+100)})});for(const row of result.shipments)snapshots.set(row.id,row);}catch(err){failed=err.message;break;}}for(const id of data.shipments.map(s=>s.id)){
  let local=data.shipments.find(s=>s.id===id);const auth={Authorization:'Bearer '+data.connection.token};
  try{
   if(local.workflowVersion===3){if(local.synced&&!snapshots.has(id))continue;const remote=local.synced?snapshots.get(id):await request(data.connection.base,'/api/v3/shipments',{method:'POST',headers:auth,body:JSON.stringify(local)});const next={...remote,synced:true,dirty:false,syncedAt:new Date().toISOString()};if(!commit({...data,shipments:data.shipments.map(s=>s.id===id?next:s)}))break;changed=true;continue;}
   if(local.synced){const remote=await request(data.connection.base,`/api/shipments/${id}`,{headers:auth});const relation=historyRelation(local,remote);if(relation==='conflict')throw new Error('Conflicting delivery updates. Keep your backup and contact the sender.');if(relation==='remote'){const latest=data.shipments.find(s=>s.id===id);if(latest.events.length!==local.events.length)continue;local={...local,status:remote.status,events:remote.events,dirty:false,synced:true,syncedAt:new Date().toISOString()};if(!commit({...data,shipments:data.shipments.map(s=>s.id===id?local:s)}))break;changed=true;}}
   local=data.shipments.find(s=>s.id===id);if(!local.dirty)continue;
   await request(data.connection.base,`/api/shipments/${id}`,{method:'PUT',headers:auth,body:JSON.stringify(local)});
   const latest=data.shipments.find(s=>s.id===id);if(!commit({...data,shipments:data.shipments.map(s=>s.id===id?{...s,synced:true,syncedAt:new Date().toISOString(),dirty:latest.events.length!==local.events.length}:s)}))break;changed=true;
  }catch(err){failed=err.message;break;}
 }}
 for(const id of data.riderJobs.map(s=>s.id)){
  try{let local=data.riderJobs.find(s=>s.id===id);if(terminal(local)&&!announce)continue;if(local.workflowVersion===3){const updated=await features.syncJob(local);if(!commit({...data,riderJobs:data.riderJobs.map(s=>s.id===id?updated:s)}))break;changed=true;continue;}const remote=await request(local.remoteBase,`/api/rider/${local.dispatchToken}`);const relation=historyRelation(local,remote);if(relation==='conflict')throw new Error('This delivery has conflicting updates. Contact the vendor.');if(relation==='remote'){local={...local,...remote,dirty:false};if(!commit({...data,riderJobs:data.riderJobs.map(s=>s.id===id?local:s)}))break;changed=true;}else if(local.dirty){for(const event of local.events.slice(remote.events.length))await request(local.remoteBase,`/api/rider/${local.dispatchToken}/events`,{method:'POST',body:JSON.stringify(event)});const latest=data.riderJobs.find(s=>s.id===id);if(!commit({...data,riderJobs:data.riderJobs.map(s=>s.id===id?{...s,dirty:latest.events.length!==local.events.length,syncedAt:new Date().toISOString()}:s)}))break;changed=true;}}
  catch(err){failed=err.message;break;}
 }
 }finally{syncing=false;if(changed&&gate==='app'&&['home','detail','success','shipments','profile','track'].includes(view)&&!app.querySelector('input:focus,textarea:focus'))render();if(announce)toast(failed?'Saved on phone. Sync failed: '+failed:'Delivery updates are synced.');}}
function exportData(){const text=JSON.stringify({format:'trackship-backup-v1',exportedAt:new Date().toISOString(),data},null,2);const name=`TrackShip-backup-${new Date().toISOString().slice(0,10)}.json`;if(window.TrackShip){window.TrackShip.exportBackup(text,name);return;}const url=URL.createObjectURL(new Blob([text],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function restoreData(e){const file=e.target.files[0];if(!file)return;try{if(file.size>5_000_000)throw new Error('This backup is too large.');const b=JSON.parse(await file.text());if(b.format!=='trackship-backup-v1'||!validateBackup(b.data))throw new Error('This is not a valid TrackShip backup.');if(!confirm('Replace the profiles and deliveries on this phone with this backup?'))return;const restored=upgradeData(b.data);if(commit(restored)){gate=restored.activeRole&&restored.accounts[restored.activeRole]?'app':'role';view='home';render();toast('Backup restored');}}catch(err){toast(err.message);}finally{e.target.value='';}}
async function publicPage(){const token=location.pathname.split('/')[2];if(!app.querySelector('.public-shell'))app.innerHTML=`<main class="public-shell">${brand()}<div class="empty"><h2>Finding your delivery…</h2></div></main>`;try{const s=await request('',`/api/track/${encodeURIComponent(token)}`);app.innerHTML=`<main class="public-shell">${brand()}<p class="eyebrow" style="text-align:center">A PACKAGE FROM ${esc(s.business)}</p><h1 style="margin:22px 0">${s.status==='Delivered'?'Your package has arrived.':s.status==='Cancelled'?'This delivery was cancelled.':'Your delivery, in view.'}</h1><div class="card shipment featured"><div class="package-top"><span class="package-thumb">${icon('box')}</span><div class="package-title"><h3>${esc(s.code)}</h3><p>${esc(s.description)}</p></div>${badge(s.status)}</div>${miniJourney(s)}<div class="route-row"><div><small>${esc(s.origin)}</small><b>${day(s.createdAt)}</b></div><div><small>${esc(s.destination)}</small><b>${esc(s.status)}</b></div></div></div>${s.workflowVersion===3?features.mapView(s):''}${timeline(s)}<div class="note">Delivery updates are recorded by the seller or rider. This page refreshes every 5 seconds. Contact your seller if you have a question.</div><p class="footer-copy">Last checked ${date(new Date())}<br>Powered by TrackShip NG · No app needed.</p></main>`;features.mountMap();}catch{app.innerHTML=`<main class="public-shell">${brand()}<div class="empty"><h2>We couldn’t find this delivery.</h2><p class="muted">Check your internet connection or ask the seller for your tracking link.</p><button class="secondary" id="retry">Try again</button></div></main>`;app.querySelector('#retry').onclick=publicPage;}}
function dispatchLanding(){app.innerHTML=`<main class="public-shell">${brand()}<div class="empty-icon">${icon('bike')}</div><h1>A delivery<br>for your next ride.</h1><p class="muted" style="margin:20px 0">Open your TrackShip app, choose the rider workspace, and tap Add delivery. Paste this page’s link to add your vendor’s dispatch.</p><div class="note">This is a private rider dispatch link. Do not forward it to anyone else.</div><button class="primary wide" id="copy-link">Copy dispatch link</button><p class="copy-status" id="copy-message"></p></main>`;app.querySelector('#copy-link').onclick=async()=>{try{await navigator.clipboard.writeText(location.href);app.querySelector('#copy-message').textContent='Copied. Paste it in the TrackShip rider app.';}catch{app.querySelector('#copy-message').textContent='Copy the link from your browser’s address bar.';}};}
window.TrackShipBack=()=>{if(gate==='pin-setup'){gate='app';render();return;}if(gate==='unlock'){gate='role';renderGate();return;}if(modal){modal=false;render();return;}if(gate==='setup'){captureSetup();if(setupStep>0)setupStep--;else gate='role';renderGate();return;}if(gate==='intro'){if(introIndex>0){introIndex--;renderGate();}else finishIntro();return;}if(gate==='role'&&data.activeRole){gate='app';render();return;}if(gate==='app'){if(view==='create'&&createStep>0){captureShipment();createStep--;render();}else navigate('home');}};
const features=createFeatures({getData:()=>data,getView:()=>view,commit,render,toast,request,esc,icon,getCurrent:current,openView:v=>navigate(v),select:id=>{selected=id;},startRider:()=>{setupRole='rider';gate='role';renderGate();},sync,openLink,shareText});
if(location.pathname.startsWith('/t/')){publicPage();setInterval(()=>{if(!document.hidden)publicPage();},5000);}else if(location.pathname.startsWith('/r/'))dispatchLanding();else if(location.pathname==='/payment-return'){app.innerHTML=`<main class="public-shell">${brand()}<h1>Return to TrackShip.</h1><p class="note">Your payment status is verified on the server. Return to the app and tap I’ve paid · check payment on your shipment.</p></main>`;}else{render();if(gate==='splash')setTimeout(()=>{gate='intro';renderGate();},650);sync();window.addEventListener('online',()=>sync());setInterval(()=>{if(!document.hidden&&gate==='app')sync();},10000);}
